/**
 * Creating a sidebar enables you to:
 * - create an ordered group of docs
 * - render a sidebar for each doc of that group
 * - provide next/previous navigation
 *
 * 5-section progressive disclosure hierarchy (max depth 3, only Start Here expanded on load).
 */

// @ts-check

// Generated by docs/scripts/sync-registry.sh — vendor categories with package pages.
// Filter to doc IDs present on disk so offline builds (without sync-registry.sh) succeed.
const fs = require('fs');
const path = require('path');

function docExists(id) {
  const base = path.join(__dirname, 'docs', id);
  return fs.existsSync(`${base}.md`) || fs.existsSync(`${base}.mdx`);
}

let packagesSidebar = [];
try {
  const raw = require('./src/data/packages-sidebar.json');
  packagesSidebar = raw
    .map((cat) => {
      const items = (cat.items || []).filter((it) =>
        typeof it === 'string' ? docExists(it) : it && it.id ? docExists(it.id) : false
      );
      if (items.length === 0) return null;
      const out = { ...cat, items };
      if (out.link && out.link.type === 'doc' && !docExists(out.link.id)) {
        delete out.link;
      }
      return out;
    })
    .filter(Boolean);
} catch {
  // No generated packages yet — sidebar will show empty
}

